def cancel_status(status: str) -> str:
    """Return the new status; no persistence or external hooks."""
    if status == "CANCELLED":
        return status
    return "CANCELLED"

export async function loadOrder(id: number) {
  const response = await fetch("/orders/" + id);
  const body = await response.json();
  return {status: body.verificationStatus};
}

Future<String> loadOrder(String base, int id) async {
  final response = await http.get(Uri.parse('$base/orders/$id'));
  final body = jsonDecode(response.body) as Map<String, dynamic>;
  return body['verifyStatus'] as String? ?? 'PENDING_VERIFY';
}
